```python
"""Payout executor.

Design
------
State machine, with SENDING as the only added status:

    (no row) --reserve--> RESERVED --update(+sent_at)--> SENDING --finish--> PAID | FAILED

* The RESERVED -> SENDING compare-and-swap is the single gate to the provider.
  It stores `sent_at` in the same atomic write that changes the status, so
  exactly one invocation, ever, wins the right to call `send`, and the
  attempt time is durable before the call is made.
* `send` is called at most once per payout, under the payout_id as the
  reference. A repeat `send` can therefore never create a second transfer,
  and the provider's 24-hour idempotency window never matters.
* A timeout, a crash, or a lost response leaves the row in SENDING. Later
  invocations only call `lookup`, which cannot move money:
    - found, accepted  -> PAID
    - found, rejected  -> FAILED (the provider rejected it)
    - not found and now - sent_at >= 900 -> FAILED (nothing can have landed)
    - not found and < 900s, or lookup timed out -> PENDING, funds stay held
* Every return value is read back from the store, so a concurrent winner's
  result is reported rather than what this invocation hoped to write.
* Finished payouts return immediately with no provider calls.
"""

ProviderTimeout = TimeoutError

_VISIBILITY_SECONDS = 900

_RESERVED = "RESERVED"
_SENDING = "SENDING"
_PAID = "PAID"
_FAILED = "FAILED"
_TERMINAL = (_PAID, _FAILED)


def _public_status(status):
    if status in _TERMINAL:
        return status
    return "PENDING"


def _current(store, payout_id):
    """The true stored status, mapped to the public vocabulary."""
    row = store.get_payout(payout_id)
    if row is None:
        return "PENDING"
    return _public_status(row["status"])


def _check_same_request(row, account, amount_minor, dest):
    if (
        row.get("account") != account
        or row.get("amount_minor") != amount_minor
        or row.get("dest") != dest
    ):
        raise ValueError(
            "payout_id %r already exists with different parameters" % (row.get("payout_id"),)
        )


def _settle_from_provider(store, payout_id, result):
    """Apply a provider result (from send or lookup) to a SENDING payout."""
    status = result.get("status") if isinstance(result, dict) else None
    provider_id = result.get("provider_id") if isinstance(result, dict) else None
    if status == "accepted":
        store.finish(payout_id, _SENDING, _PAID, provider_id=provider_id)
    elif status == "rejected":
        store.finish(payout_id, _SENDING, _FAILED, provider_id=provider_id,
                     reason="provider_rejected")
    # Anything else is unknown: leave the funds held. If finish returned False,
    # another invocation already finished the payout; either way, read it back.
    return _current(store, payout_id)


def execute_payout(store, provider, payout_id, account, amount_minor, dest, now) -> str:
    """Returns the payout's current status: "PAID", "FAILED", "PENDING" or "INSUFFICIENT"."""
    reference = str(payout_id)

    row = store.get_payout(payout_id)
    if row is None:
        outcome = store.reserve(payout_id, account, amount_minor, dest)
        if outcome == "INSUFFICIENT":
            return "INSUFFICIENT"
        row = store.get_payout(payout_id)
        if row is None:  # should be impossible after CREATED/EXISTS
            return "PENDING"

    _check_same_request(row, account, amount_minor, dest)

    status = row["status"]
    if status in _TERMINAL:
        return status

    if status == _RESERVED:
        # Durably record the attempt time and claim the only send, atomically.
        if not store.update(payout_id, _RESERVED, _SENDING, sent_at=now):
            return _current(store, payout_id)
        try:
            result = provider.send(reference, row["dest"], row["amount_minor"])
        except ProviderTimeout:
            # The transfer may or may not have landed; the row stays SENDING.
            return _current(store, payout_id)
        return _settle_from_provider(store, payout_id, result)

    if status == _SENDING:
        sent_at = row.get("sent_at")
        try:
            found = provider.lookup(reference)
        except ProviderTimeout:
            return _current(store, payout_id)

        if found is not None:
            return _settle_from_provider(store, payout_id, found)

        if sent_at is not None and now - sent_at >= _VISIBILITY_SECONDS:
            # The provider has no record and anything sent would be visible by now.
            store.finish(payout_id, _SENDING, _FAILED, reason="not_found_after_900s")
        return _current(store, payout_id)

    return _public_status(status)
